PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE,phone TEXT UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('buyer','seller','admin')),verified INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS seller_profiles(user_id INTEGER PRIMARY KEY,bio TEXT,location TEXT,payout_method TEXT,bank_account TEXT,mpesa_phone TEXT,rating REAL DEFAULT 0,total_sales INTEGER DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,type TEXT NOT NULL CHECK(type IN ('service','goods','both')));
CREATE TABLE IF NOT EXISTS listings(id INTEGER PRIMARY KEY AUTOINCREMENT,seller_id INTEGER NOT NULL,category_id INTEGER,title TEXT NOT NULL,description TEXT NOT NULL,price INTEGER NOT NULL,currency TEXT DEFAULT 'KES',kind TEXT NOT NULL CHECK(kind IN ('service','goods')),stock INTEGER DEFAULT 1,delivery_available INTEGER DEFAULT 0,status TEXT DEFAULT 'active',created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(seller_id) REFERENCES users(id),FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,buyer_id INTEGER NOT NULL,seller_id INTEGER NOT NULL,listing_id INTEGER NOT NULL,amount INTEGER NOT NULL,commission INTEGER NOT NULL,payout_amount INTEGER NOT NULL,payment_method TEXT,status TEXT DEFAULT 'awaiting_payment',payment_ref TEXT,delivery_status TEXT DEFAULT 'not_required',buyer_note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,approved_at TEXT,FOREIGN KEY(buyer_id) REFERENCES users(id),FOREIGN KEY(seller_id) REFERENCES users(id),FOREIGN KEY(listing_id) REFERENCES listings(id));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER,sender_id INTEGER NOT NULL,body TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(sender_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,provider TEXT NOT NULL,provider_ref TEXT,status TEXT NOT NULL,amount INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS payouts(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,seller_id INTEGER NOT NULL,amount INTEGER NOT NULL,method TEXT NOT NULL,status TEXT DEFAULT 'pending',provider_ref TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(seller_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS disputes(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,opened_by INTEGER NOT NULL,reason TEXT NOT NULL,status TEXT DEFAULT 'open',resolution TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(opened_by) REFERENCES users(id));
